export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  let t = time;

  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = apexHeight;

  if (t >= apexTime) {
    const dt = t - apexTime;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
  }

  const scaleY = 120;
  const originY = 320;

  const tossY = originY - tossedHeight * scaleY;
  const dropY = originY - dropHeight * scaleY;

  let tossState = "Rising";
  if (t < 0.05) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.05) tossState = "At the top";
  else if (t > apexTime) tossState = "Falling";
  if (tossedHeight <= 0.01 && t > 0.5) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) < 0.05) dropState = "Just released";
  else if (t > apexTime) dropState = "Falling together";
  if (dropHeight <= 0.01 && t > apexTime) dropState = "At launch height";

  const objects = [];

  objects.push(...sdk.panel({
    x: 40, y: 50, w: 260, h: 340,
    title: "Toss Lane",
    state: tossState,
    id: "lane.toss"
  }));

  objects.push(...sdk.panel({
    x: 340, y: 50, w: 260, h: 340,
    title: "Drop Lane",
    state: dropState,
    id: "lane.drop"
  }));

  objects.push(sdk.circle("ball.toss", 170, tossY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 470, dropY, 28, { role: "output" }));

  if (t >= apexTime) {
    objects.push(sdk.gate("gate", 470, originY - apexHeight * scaleY, { open: true, label: "Gate" }));
  } else {
    objects.push(sdk.gate("gate", 470, originY - apexHeight * scaleY, { open: false, label: "Gate" }));
  }

  objects.push(...sdk.vector("vec.v.toss", { x: 140, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: 200, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: 440, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: 500, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.callout(220, tossY - 30, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 1) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(520, dropY - 30, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 1) + " m/s^2"
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
